public static void MergeSort(int[] A, int s, int e)
{
    if (s >= e)
        return;

    // Find the middle point
    int m = (s + e) / 2;

    // Sort first halve
    MergeSort(A, s, m);
    // Sort second halve
    MergeSort(A, m + 1, e);

    // Merge the sorted halves
    Merge(A, s, m, e);
}

